def plan(scenarios, budget):
    ordered = sorted(scenarios, key=lambda s: (-s['likelihood'] * s['impact'], -s['impact'], s['name']))
    selected, untested, used = [], [], 0
    for s in ordered:
        if used + s['hours'] <= budget:
            selected.append(s['name'])
            used += s['hours']
        else:
            untested.append((s['name'], s['likelihood'] * s['impact']))
    return {'selected': selected, 'untested': untested, 'hours_used': used}
